const askAfterConnect = async (url: string, outbound: unknown): Promise<{connected: Frame; frames: Frame[]}> => {
  const message = typeof outbound === 'string' ? JSON.parse(outbound) : outbound;
  const result = await exchangeAfterConnect(url, [message, {type: 'ping', timestamp: 1}]);
  return result as {connected: Frame; frames: Frame[]};
};

